async function testDatabaseConnection() {
  const url = process.env.DATABASE_URL;
  if (!url) {
    console.log('❌ DATABASE_URL not set');
    return false;
  }

  console.log('\n📊 Testing DATABASE_URL connectivity...');
  console.log(`   URL: ${url.split('@')[0]}@***`);

