}

validateCredentials();

// Test script to verify credentials from .env.test
// Uses only Node.js built-in modules - no external dependencies required

const https = require('https');
const http = require('http');
const fs = require('fs');
const net = require('net');
const path = require('path');

// Simple .env file parser
function parseEnvFile(filePath) {
  try {
    const content = fs.readFileSync(filePath, 'utf8');
    const env = {};

    for (const line of content.split('\n')) {
      const trimmed = line.trim();
      // Skip comments and empty lines
      if (!trimmed || trimmed.startsWith('#')) continue;

      // Parse KEY=VALUE pairs
      const eqIndex = trimmed.indexOf('=');
      if (eqIndex > 0) {
        const key = trimmed.substring(0, eqIndex).trim();
        let value = trimmed.substring(eqIndex + 1).trim();

        // Remove surrounding quotes if present
        if ((value.startsWith('"') && value.endsWith('"')) ||
            (value.startsWith("'") && value.endsWith("'"))) {
          value = value.slice(1, -1);
        }

        env[key] = value;
      }
    }

    return env;
  } catch (error) {
    console.error(`Error reading env file: ${error.message}`);
    return {};
  }
}

// Load environment variables from .env.test
const envPath = path.join(__dirname, '.env.test');
const process.env = parseEnvFile(envPath);

// Simple HTTP request helper
function makeRequest(options, body = null) {
  return new Promise((resolve) => {
    let url = options.url || 'http://localhost';
    if (!url.startsWith('http')) {
      url = 'http://' + url;
    }

    const parsedUrl = new URL(url);

    const requestOptions = {
      hostname: parsedUrl.hostname,
      port: parsedUrl.protocol === 'https:' ? 443 : 80,
      path: parsedUrl.pathname + parsedUrl.search,
      method: options.method || 'GET',
      headers: {
        ...options.headers,
        'User-Agent': 'credential-test/1.0'
      }
    };

    const req = (parsedUrl.protocol === 'https:' ? https : http).request(requestOptions, (res) => {
      let data = '';
      res.on('data', chunk => data += chunk);
      res.on('end', () => {
        resolve({
          statusCode: res.statusCode,
          headers: res.headers,
          body: data
        });
      });
    });

    req.on('error', (error) => {
      resolve({ error: error.message });
    });

    if (body) {
      req.write(body);
    }

    req.end();
  });
}

async function testDatabaseConnection() {
  const url = process.env.DATABASE_URL;
  if (!url) {
