// Test script to verify credentials from .env.test
// This script tests database connectivity and API key validity

require('dotenv').config({ path: './.env.test' });

const { Pool } = require('pg');
const AWS = require('aws-sdk');
const axios = require('axios');

// Helper function to load env vars safely
const loadEnv = (key) => {
  const value = process.env[key];
  if (!value) {
    console.log(`❌ ${key}: Not set`);
    return null;
  }
  return value;
};

console.log('=== Credential Verification ===\n');

// 1. Database Connection Test
const testDatabase = async () => {
  const url = loadEnv('DATABASE_URL');
  if (!url) return;

  console.log('Testing DATABASE_URL...');

  try {
    const pool = new Pool({ connectionString: url });
    const client = await pool.connect();
    await client.query('SELECT 1');
    client.release();
    console.log('✅ Database connection successful');
  } catch (error) {
    if (error.code === 'ECONNREFUSED' || error.code === 'ETIMEDOUT') {
      console.log('❌ Database connection failed: Connection refused/timed out');
    } else if (error.message.includes('password authentication') || error.code === '28P01') {
      console.log('❌ Database connection failed: Authentication error (credentials may be invalid)');
    } else {
      console.log(`❌ Database connection failed: ${error.message}`);
    }
  } finally {
    console.log();
  }
};

// 2. AWS Credentials Test
const testAWS = async () => {
  const accessKeyId = loadEnv('AWS_ACCESS_KEY_ID');
  const secretAccessKey = loadEnv('AWS_SECRET_ACCESS_KEY');

  if (!accessKeyId || !secretAccessKey) return;

  console.log('Testing AWS credentials...');

  try {
    AWS.config.update({ accessKeyId, secretAccessKey });
    const sts = new AWS.STS();
    await sts.getCallerIdentity().promise();
