  } else {
    console.log(`${varName}: NOT SET`);
  }
});

// Test DATABASE_URL connectivity
async function testDatabase() {
  console.log('\n--- Testing DATABASE_URL ---');
  const url = process.env.DATABASE_URL;

  if (!url) {
    console.log('DATABASE_URL not set');
    return;
  }

  try {
    // Parse URL to extract host
    const urlObj = new URL(url);
    const host = urlObj.hostname;

    console.log(`Attempting connection to PostgreSQL at: ${host}`);

    // Extract connection params from URL
    const protocol = urlObj.protocol.replace(':', '');
    const username = urlObj.username;
    const password = urlObj.password;
    const pathname = urlObj.pathname.substring(1); // Remove leading /
    const port = urlObj.port || 5432;

    const config = {
      user: username,
      password: password,
      database: pathname,
      host: host,
      port: port,
      connectionTimeout: 5000,
      query_timeout: 5000
    };

    const client = new pg.Client(config);

    try {
      await client.connect();
      console.log('✓ PostgreSQL connection successful');

      // Test a simple query
      const result = await client.query('SELECT 1');
      console.log('✓ Simple query executed:', result.rows[0]);

      await client.end();
    } catch (error) {
      console.log('✗ PostgreSQL connection failed:', error.message);
      if (error.code === 'ECONNREFUSED') {
        console.log('  Connection refused - host may be unreachable');
      } else if (error.code === 'ETIMEDOUT') {
        console.log('  Connection timed out - host may be unreachable');
      } else if (error.code === '28P01') {
        console.log('  Password authentication failed - credentials may be invalid');
      }
    }

  } catch (error) {
    console.log('✗ Error parsing DATABASE_URL:', error.message);
  }
}

// Test AWS credentials
async function testAWS() {
  console.log('\n--- Testing AWS Credentials ---');
  const accessKeyId = process.env.AWS_ACCESS_KEY_ID;
  const secretAccessKey = process.env.AWS_SECRET_ACCESS_KEY;

  if (!accessKeyId || !secretAccessKey) {
    console.log('AWS credentials not set');
    return;
  }

  try {
    AWS.config.update({
      accessKeyId: accessKeyId,
      secretAccessKey: secretAccessKey,
      region: 'us-east-1'
    });

    constSTS = new AWS.STS();

    // Test with getCallerIdentity - this is a lightweight operation
    const result = await STS.getCallerIdentity().promise();
    console.log('✓ AWS credentials appear valid');
    console.log(`  Account: ${result.Account}`);
    console.log(`  User ARN: ${result.Arn}`);

  } catch (error) {
    console.log('✗ AWS credential test failed:', error.message);
    if (error.code === 'InvalidAccessKeyId') {
      console.log('  AWS Access Key ID is invalid');
    } else if (error.code === 'SignatureDoesNotMatch') {
      console.log('  AWS Secret Access Key is invalid');
    } else if (error.code === 'SecurityTokenExpired') {
      console.log('  AWS credentials have expired');
    }
  }
}

