#!/usr/bin/env node

/**
 * Environment Variable Validation Script
 * Tests connectivity and validity of credentials stored in .env.test
 */

require('dotenv').config({ path: '.env.test' });

const fs = require('fs');
const https = require('https');
const http = require('http');
const { URL } = require('url');
const { Client } = require('pg'); // PostgreSQL client
const crypto = require('crypto');

// Configuration
const ENV_FILE = '.env.test';
const TIMEOUT = 5000; // 5 seconds timeout

// Colors for terminal output
const COLORS = {
  SUCCESS: '\x1b[32m',
  FAILURE: '\x1b[31m',
  WARNING: '\x1b[33m',
  RESET: '\x1b[0m',
};

// Results storage
const results = {
  valid: [],
  invalid: [],
  skipped: [],
  errors: [],
};

/**
 * Helper function to log results
 */
function log(message, type = 'info') {
  const prefix = {
    success: `${COLORS.SUCCESS}[✓]${COLORS.RESET}`,
    failure: `${COLORS.FAILURE}[✗]${COLORS.RESET}`,
    warning: `${COLORS.WARNING}[⚠]${COLORS.RESET}`,
    info: '[•]',
  }[type] || '[ ]';

  console.log(`${prefix} ${message}`);
}

/**
 * Check if a file exists
 */
function fileExists(filepath) {
  return fs.existsSync(filepath);
}

/**
 * Parse DATABASE_URL and test connectivity
 */
async function testDatabaseUrl() {
  const url = process.env.DATABASE_URL;
  if (!url) {
    log('DATABASE_URL not found in environment', 'warning');
    results.skipped.push('DATABASE_URL');
    return;
  }

  try {
    const parsed = new URL(url);
    log(`Testing connection to ${parsed.hostname}...`, 'info');

    // For PostgreSQL using pg package
    try {
      const { Client } = require('pg');
      const client = new Client({ connectionString: url, connectionTimeoutMillis: 5000 });

      await client.connect();
      log('Successfully connected to PostgreSQL database', 'success');
      results.valid.push('DATABASE_URL');
      await client.end();
    } catch (pgError) {
      // pg package might not be installed
      log(`pg package not available: ${pgError.message}`, 'warning');
      log('Attempting basic connectivity test...', 'info');

      // Fallback: basic connectivity test using net module
      try {
        const net = require('net');
        return new Promise((resolve) => {
          const socket = new net.Socket();
          const timeout = setTimeout(() => {
            socket.destroy();
            log('Database connection timed out', 'failure');
            results.invalid.push('DATABASE_URL');
            resolve();
          }, 5000);

          socket.on('connect', () => {
            clearTimeout(timeout);
            socket.destroy();
            log('Database server is reachable', 'success');
            results.valid.push('DATABASE_URL');
            resolve();
          });

          socket.on('error', (err) => {
            clearTimeout(timeout);
            log(`Database connection failed: ${err.message}`, 'failure');
            results.invalid.push('DATABASE_URL');
            resolve();
          });

          socket.connect({
            host: parsed.hostname,
            port: parsed.port || 5432,
          });
        });
      } catch (netError) {
        log(`Basic connectivity test failed: ${netError.message}`, 'failure');
        results.invalid.push('DATABASE_URL');
      }
    }
  } catch (error) {
    log(`Error parsing DATABASE_URL: ${error.message}`, 'failure');
    results.errors.push({ variable: 'DATABASE_URL', error: error.message });
  }
}

/**
 * Test AWS credentials
 */
async function testAwsCredentials() {
  const accessKeyId = process.env.AWS_ACCESS_KEY_ID;
  const secretAccessKey = process.env.AWS_SECRET_ACCESS_KEY;

  if (!accessKeyId || !secretAccessKey) {
    log('AWS credentials not found in environment', 'warning');
    results.skipped.push('AWS_ACCESS_KEY_ID');
    results.skipped.push('AWS_SECRET_ACCESS_KEY');
    return;
  }

  try {
    // Check if AWS SDK is available
    try {
      const AWS = require('aws-sdk');
      AWS.config.update({ 
        accessKeyId, 
        secretAccessKey,
        region: 'us-east-1',
      });

      const sts = new AWS.STS();
      const data = await sts.getCallerIdentity({}).promise();

      log(`AWS credentials valid - Account: ${data.Account}`, 'success');
      results.valid.push('AWS_ACCESS_KEY_ID');
      results.valid.push('AWS_SECRET_ACCESS_KEY');
    } catch (awsError) {
      log(`AWS SDK error: ${awsError.message}`, 'info');

      // Fallback: simple credential format validation
      if (accessKeyId.startsWith('AKIA') && accessKeyId.length === 20) {
        log('AWS Access Key ID format appears valid', 'success');
        results.valid.push('AWS_ACCESS_KEY_ID');
      } else {
        log('AWS Access Key ID format is invalid', 'failure');
        results.invalid.push('AWS_ACCESS_KEY_ID');
      }

      if (secretAccessKey && secretAccessKey.length >= 20) {
        log('AWS Secret Access Key format appears valid', 'success');
        results.valid.push('AWS_SECRET_ACCESS_KEY');
      } else {
        log('AWS Secret Access Key format is invalid', 'failure');
        results.invalid.push('AWS_SECRET_ACCESS_KEY');
      }
    }
  } catch (error) {
    log(`Error testing AWS credentials: ${error.message}`, 'failure');
    results.errors.push({ variable: 'AWS_CREDENTIALS', error: error.message });
  }
}

/**
 * Test Anthropic API key
 */
async function testAnthropicKey() {
  const apiKey = process.env.ANTHROPIC_API_KEY;
  if (!apiKey) {
    log('ANTHROPIC_API_KEY not found in environment', 'warning');
    results.skipped.push('ANTHROPIC_API_KEY');
    return;
  }

  try {
    const options = {
      hostname: 'api.anthropic.com',
      port: 443,
      path: '/v1/messages',
