#!/usr/bin/env node

/**
 * Environment Variable Validation Script
 * Tests connectivity and validity of credentials stored in .env.test
 * Uses only built-in Node.js modules - no external dependencies required
 */

const fs = require('fs');
const https = require('https');
const http = require('http');
const { URL } = require('url');
const net = require('net');

// Load .env.test manually (no dotenv dependency)
function loadEnvFile(filepath) {
  if (!fs.existsSync(filepath)) {
    console.error(`Error: ${filepath} not found`);
    process.exit(1);
  }

  const envContent = fs.readFileSync(filepath, 'utf8');
  const envMap = {};

  for (const line of envContent.split('\n')) {
    const trimmedLine = line.trim();
    if (!trimmedLine || trimmedLine.startsWith('#')) continue;

    const eqIndex = trimmedLine.indexOf('=');
    if (eqIndex > 0) {
      const key = trimmedLine.substring(0, eqIndex).trim();
      let value = trimmedLine.substring(eqIndex + 1).trim();

      // Remove quotes if present
      if ((value.startsWith('"') && value.endsWith('"')) || 
          (value.startsWith("'") && value.endsWith("'"))) {
        value = value.slice(1, -1);
      }

      envMap[key] = value;
    }
  }

  return envMap;
}

// Configuration
const ENV_FILE = '.env.test';
const TIMEOUT = 5000; // 5 seconds timeout

// Colors for terminal output
const COLORS = {
  SUCCESS: '\x1b[32m',
  FAILURE: '\x1b[31m',
  WARNING: '\x1b[33m',
  RESET: '\x1b[0m',
};

// Results storage
const results = {
  valid: [],
  invalid: [],
  skipped: [],
  errors: [],
};

/**
 * Helper function to log results
 */
function log(message, type = 'info') {
  const prefix = {
    success: `${COLORS.SUCCESS}[✓]${COLORS.RESET}`,
    failure: `${COLORS.FAILURE}[✗]${COLORS.RESET}`,
    warning: `${COLORS.WARNING}[⚠]${COLORS.RESET}`,
    info: '[•]',
  }[type] || '[ ]';

  console.log(`${prefix} ${message}`);
}

/**
 * Test connectivity to a host and port
 */
function testConnectivity(hostname, port, timeout = TIMEOUT) {
  return new Promise((resolve) => {
    const socket = new net.Socket();
    const timer = setTimeout(() => {
      socket.destroy();
      log(`${hostname}:${port} - connection timed out`, 'info');
      resolve(false);
    }, timeout);

    socket.on('connect', () => {
      clearTimeout(timer);
      socket.destroy();
      log(`${hostname}:${port} - successfully connected`, 'success');
      resolve(true);
    });

    socket.on('error', (err) => {
      clearTimeout(timer);
      log(`${hostname}:${port} - connection failed: ${err.message}`, 'info');
      resolve(false);
    });

    socket.connect({ hostname, port });
  });
}

/**
 * Parse DATABASE_URL and test connectivity
 */
async function testDatabaseUrl(env) {
  const url = env.DATABASE_URL;
  if (!url) {
    log('DATABASE_URL not found in environment', 'warning');
    results.skipped.push('DATABASE_URL');
    return;
  }

  try {
    const parsed = new URL(url);
    log(`Testing connection to PostgreSQL server at ${parsed.hostname}:${parsed.port || 5432}...`, 'info');

    const isConnected = await testConnectivity(parsed.hostname, parsed.port || 5432);

    if (isConnected) {
      log('PostgreSQL server is reachable', 'success');
      results.valid.push('DATABASE_URL');
    } else {
      log('PostgreSQL server is not reachable', 'failure');
      results.invalid.push('DATABASE_URL');
    }
  } catch (error) {
    log(`Error parsing DATABASE_URL: ${error.message}`, 'failure');
    results.errors.push({ variable: 'DATABASE_URL', error: error.message });
  }
}

/**
 * Test AWS credentials
 */
async function testAwsCredentials(env) {
  const accessKeyId = env.AWS_ACCESS_KEY_ID;
  const secretAccessKey = env.AWS_SECRET_ACCESS_KEY;

  if (!accessKeyId || !secretAccessKey) {
    log('AWS credentials not found in environment', 'warning');
    results.skipped.push('AWS_ACCESS_KEY_ID');
    results.skipped.push('AWS_SECRET_ACCESS_KEY');
    return;
  }

  // Validate AWS Access Key ID format
  const isValidAccessKey = accessKeyId.startsWith('AKIA') && accessKeyId.length === 20;

  // Validate AWS Secret Access Key format (typically 40 characters)
  const isValidSecretKey = secretAccessKey.length >= 20;

  if (isValidAccessKey) {
    log('AWS Access Key ID format appears valid (AKIA prefix, 20 chars)', 'success');
    results.valid.push('AWS_ACCESS_KEY_ID');
  } else {
    log(`AWS Access Key ID format is invalid: ${accessKeyId.length} chars, starts with: ${accessKeyId.slice(0,4)}`, 'failure');
    results.invalid.push('AWS_ACCESS_KEY_ID');
  }

  if (isValidSecretKey) {
