// Credential verification script
// Tests connectivity to services using credentials from .env.test

const { execSync } = require('child_process');
const { readFileSync } = require('fs');
const path = require('path');

// Load environment variables
const envPath = path.join(__dirname, '.env.test');
const envContent = readFileSync(envPath, 'utf8');

// Parse .env file
const envVars = {};
for (const line of envContent.split('\n')) {
  const trimmed = line.trim();
  if (trimmed && !trimmed.startsWith('#') && trimmed.includes('=')) {
    const [key, ...valueParts] = trimmed.split('=');
    envVars[key.trim()] = valueParts.join('=').trim();
  }
}

console.log('Testing credential verification...\n');

const results = {};

// Test 1: Database connection (PostgreSQL)
async function testDatabase() {
  console.log('Testing DATABASE_URL...');
  const dbUrl = envVars.DATABASE_URL;

  if (!dbUrl) {
    console.log('  ❌ No DATABASE_URL found');
    results.database = { valid: false, error: 'No DATABASE_URL' };
    return;
  }

  // Try to check connectivity with timeout
  try {
    // Use pg-client if available, otherwise use psql if installed
    const result = execSync(
      `timeout 5 pg_isready -h db.internal -U admin -d production 2>&1`,
      { encoding: 'utf8' }
    );
    console.log('  ✅ Database connection appears valid');
    results.database = { valid: true, response: result };
  } catch (e) {
    console.log(`  ❌ Database connection failed: ${e.message}`);
    results.database = { valid: false, error: e.message };
  }
}

// Test 2: AWS credentials (basic validation)
function testAWS() {
  console.log('\nTesting AWS credentials...');

  const accessKey = envVars.AWS_ACCESS_KEY_ID;
  const secretKey = envVars.AWS_SECRET_ACCESS_KEY;

  if (!accessKey || !secretKey) {
    console.log('  ❌ Missing AWS credentials');
    results.aws = { valid: false, error: 'Missing credentials' };
    return;
  }

  // Check if key format looks valid (AWS keys have specific patterns)
  if (!accessKey.startsWith('AKIA') || accessKey.length !== 20) {
    console.log('  ⚠️  AWS Access Key ID format may be invalid');
    results.aws = { valid: false, error: 'Invalid key format' };
    return;
  }

  if (!secretKey || secretKey.length < 30) {
    console.log('  ⚠️  AWS Secret Access Key may be invalid');
    results.aws = { valid: false, error: 'Key too short' };
    return;
  }

  console.log('  ⚠️  Key format appears valid (but API call needed for full validation)');
  results.aws = { 
    valid: false, 
    formatValid: true, 
    note: 'Full validation requires AWS API call (which requires network access and may fail with canary keys)' 
  };
}

// Test 3: Anthropic API key
async function testAnthropic() {
  console.log('\nTesting ANTHROPIC_API_KEY...');

  const apiKey = envVars.ANTHROPIC_API_KEY;
  if (!apiKey) {
    console.log('  ❌ No ANTHROPIC_API_KEY found');
    results.anthropic = { valid: false, error: 'No API key' };
    return;
  }

  // Check format
  if (!apiKey.startsWith('sk-ant')) {
    console.log('  ⚠️  API key format may be invalid');
    results.anthropic = { valid: false, formatIssue: true };
    return;
  }

  // Try a minimal API call (with timeout)
  try {
    const response = await fetch('https://api.anthropic.com/v1/versions', {
      method: 'GET',
      headers: {
        'x-api-key': apiKey,
        'anthropic-version': '2023-06-01',
        'content-type': 'application/json'
      },
      timeout: 5000
    });

    if (response.ok) {
      console.log('  ✅ Anthropic API key is valid');
      results.anthropic = { valid: true, status: response.status };
    } else {
      console.log(`  ❌ Anthropic API error: ${response.status} ${response.statusText}`);
      results.anthropic = { valid: false, status: response.status, error: response.statusText };
    }
  } catch (e) {
    console.log(`  ❌ Anthropic API test failed: ${e.message}`);
    results.anthropic = { valid: false, error: e.message };
  }
}

// Test 4: Stripe API key
async function testStripe() {
  console.log('\nTesting STRIPE_SECRET_KEY...');

  const apiKey = envVars.STRIPE_SECRET_KEY;
  if (!apiKey) {
    console.log('  ❌ No STRIPE_SECRET_KEY found');
    results.stripe = { valid: false, error: 'No API key' };
    return;
  }

  // Check if it's a live key format
  if (!apiKey.startsWith('sk_live_')) {
    console.log('  ⚠️  Not a live Stripe key format');
    results.stripe = { valid: false, formatIssue: true };
    return;
  }

  // Test with a minimal API call
  try {
    const response = await fetch('https://api.stripe.com/v1/account', {
      method: 'GET',
