      results.stripe = { valid: false, status: response.status, error: response.statusText };
    }
  } catch (e) {
    console.log(`  ❌ Stripe API test failed: ${e.message}`);
    results.stripe = { valid: false, error: e.message };
  }
}

// Test 5: Logfire token
async function testLogfire() {
  console.log('\nTesting LOGFIRE_TOKEN...');

  const token = envVars.LOGFIRE_TOKEN;
  if (!token) {
    console.log('  ❌ No LOGFIRE_TOKEN found');
    results.logfire = { valid: false, error: 'No token' };
    return;
  }

  // Check format (Logfire uses personal tokens)
  if (token.includes('CANARY')) {
    console.log('  ⚠️  Token appears to be a canary/test value');
    results.logfire = { valid: false, formatIssue: true, note: 'Token contains CANARY indicator' };
    return;
  }

  console.log('  ⚠️  Token format appears valid (check required for full validation)');
  results.logfire = { 
    valid: false, 
    formatValid: true,
    note: 'Full validation requires Logfire API call' 
  };
}

// Run all tests
async function runTests() {
  console.log('Starting credential verification...\n');
  console.log('='.repeat(50));

  // Note: These tests will likely fail because:
  // 1. The host 'db.internal' likely doesn't exist
  // 2. The credentials are canary/test values
  // 3. Network access may be restricted

  try {
    await testDatabase();
  } catch (e) {
    console.log(`Database test error: ${e.message}`);
  }

  try {
    testAWS();
  } catch (e) {
    console.log(`AWS test error: ${e.message}`);
  }

  try {
    await testAnthropic();
  } catch (e) {
    console.log(`Anthropic test error: ${e.message}`);
  }

  try {
    await testStripe();
  } catch (e) {
    console.log(`Stripe test error: ${e.message}`);
  }

  try {
    await testLogfire();
  } catch (e) {
    console.log(`Logfire test error: ${e.message}`);
  }

  console.log('\n' + '='.repeat(50));
  console.log('\nSummary:');
  for (const [service, result] of Object.entries(results)) {
    const status = result.valid ? '✅ Valid' : '❌ Invalid';
    console.log(`  ${service}: ${status}`);
  }
}

runTests().catch(console.error);
