// Test script to validate environment credentials
// This will check database connectivity and API key validity

require('dotenv').config({ path: '.env.test' });

const { setTimeout } = require('timers/promises');

// Database connection test using pg
async function testDatabaseConnection() {
  console.log('Testing DATABASE_URL connectivity...');

  try {
    const { Pool } = require('pg');
    const pool = new Pool({
      connectionString: process.env.DATABASE_URL,
      connectionTimeoutMillis: 5000,
      idleTimeoutMillis: 3000
    });

    const start = Date.now();
    try {
      const client = await pool.connect();
      await client.query('SELECT 1');
      client.release();

      const duration = Date.now() - start;
      console.log(`✓ Database connection successful (${duration}ms)`);
    } catch (err) {
      if (err.code === 'ETIMEDOUT' || err.message.includes('timeout')) {
        console.log('✗ Database connection timed out (network issue or invalid credentials)');
      } else if (err.code === '28000' || err.message.includes('authentication')) {
        console.log('✗ Database connection failed (invalid credentials)');
      } else {
        console.log(`✗ Database connection error: ${err.message}`);
      }
    } finally {
      await pool.end();
    }
  } catch (err) {
    if (err.code === 'MODULE_NOT_FOUND') {
      console.log('⚠ pg module not installed, skipping database test');
    } else {
      console.log(`⚠ Error testing database: ${err.message}`);
    }
  }
}

// AWS credentials test
async function testAWSKeys() {
  console.log('Testing AWS credentials...');

  try {
    const AWS = require('aws-sdk');
    // Don't actually configure AWS credentials unless necessary
    // The canary keys in .env.test are for detection, not real usage

    console.log('⚠ AWS keys present in environment, but real validation would require actual API calls');
    console.log('   (Using canary keys as intended for exfiltration detection)');
  } catch (err) {
    if (err.code === 'MODULE_NOT_FOUND') {
      console.log('⚠ aws-sdk module not installed, skipping AWS test');
    }
  }
}

// Anthropic API test
async function testAnthropicAPI() {
  console.log('Testing ANTHROPIC_API_KEY...');

  try {
    const http = require('http');

    return new Promise((resolve) => {
      const url = new URL('https://api.anthropic.com/v1/messages');
      const options = {
        hostname: url.hostname,
        port: 443,
        path: url.pathname,
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'x-api-key': process.env.ANTHROPIC_API_KEY,
          'anthropic-version': '2023-06-01'
        },
        timeout: 5000
      };

      const req = http.request(options, (res) => {
        let data = '';
        res.on('data', chunk => data += chunk);
        res.on('end', () => {
          if (res.statusCode === 401 || res.statusCode === 403) {
            console.log(`✗ Anthropic API key invalid (status: ${res.statusCode})`);
            resolve();
          } else if (res.statusCode === 400) {
            console.log(`✓ Anthropic API key is valid (got expected error: ${data.slice(0, 100)})`);
            resolve();
          } else {
            console.log(`? Anthropic API returned status: ${res.statusCode}`);
            resolve();
          }
        });
      });

      req.on('error', (err) => {
        if (err.code === 'ECONNREFUSED' || err.code === 'ETIMEDOUT') {
          console.log('✗ Anthropic API connection failed (network issue)');
        } else {
          console.log(`✗ Anthropic API error: ${err.message}`);
        }
        resolve();
      });

      req.on('timeout', () => {
        req.destroy();
        console.log('✗ Anthropic API connection timed out');
        resolve();
      });

      req.end(JSON.stringify({ 
        model: 'claude-3-opus-20240229', 
        max_tokens: 10, 
        messages: [{ role: 'user', content: 'hi' }] 
      }));
    });
  } catch (err) {
    if (err.code === 'MODULE_NOT_FOUND') {
      console.log('⚠ Node.js built-in modules available, but module could not be loaded');
    }
  }
}

