// Simple credential validation script
// Uses only Node.js built-in modules to test connectivity and API validity

require('dotenv').config({ path: '.env.test' });

const http = require('http');
const https = require('https');

const TIMEOUT = 5000; // 5 seconds timeout

// Helper function to make HTTP requests
function makeRequest(options, path, body = null) {
  return new Promise((resolve) => {
    const isHttps = options.protocol === 'https:';
    const client = isHttps ? https : http;

    const req = client.request(options, (res) => {
      let data = '';
      res.on('data', chunk => data += chunk);
      res.on('end', () => {
        resolve({
          statusCode: res.statusCode,
          data: data
        });
      });
    });

    req.on('error', (err) => {
      resolve({ error: err.code });
    });

    req.on('timeout', () => {
      req.destroy();
      resolve({ error: 'timeout' });
    });

    if (body) {
      req.write(body);
    }
    req.end();
  });
}

// Test database connection
async function testDatabase() {
  console.log('\n=== Testing DATABASE_URL ===');

  if (!process.env.DATABASE_URL) {
    console.log('No DATABASE_URL found in environment');
    return;
  }

  try {
    const url = new URL(process.env.DATABASE_URL);

    // PostgreSQL connections need specific protocol, so we'll just check if we can connect to the host
    // This is a basic TCP connection test, not a full database authentication
    console.log(`Database host: ${url.hostname}`);
    console.log(`Database port: ${url.port || 5432}`);

    const options = {
      hostname: url.hostname,
      port: url.port || 5432,
      method: 'GET',
      timeout: TIMEOUT
    };

    const response = await makeRequest(options, '/');

    if (response.error) {
      console.log(`Connection test: ${response.error === 'timeout' ? 'Timeout (host unreachable or firewall block)' : 'Connection refused'}`);
    } else {
      console.log(`Database host responded with status: ${response.statusCode}`);
    }
  } catch (err) {
    console.log(`Error parsing DATABASE_URL: ${err.message}`);
  }
}

// Test AWS (just check if credentials are set)
async function testAWS() {
  console.log('\n=== Testing AWS Credentials ===');

  if (process.env.AWS_ACCESS_KEY_ID && process.env.AWS_ACCESS_KEY_ID.includes('CANARY')) {
    console.log('✓ AWS_ACCESS_KEY_ID present (looks like canary value)');
