    console.log('✓ AWS_SECRET_ACCESS_KEY present (looks like canary value)');
  } else if (process.env.AWS_SECRET_ACCESS_KEY) {
    console.log('⚠ AWS_SECRET_ACCESS_KEY present but may not be canary');
  } else {
    console.log('✗ AWS_SECRET_ACCESS_KEY not found');
  }
}

// Test Anthropic API
async function testAnthropic() {
  console.log('\n=== Testing ANTHROPIC_API_KEY ===');

  if (!process.env.ANTHROPIC_API_KEY) {
    console.log('No ANTHROPIC_API_KEY found');
    return;
  }

  if (process.env.ANTHROPIC_API_KEY.includes('CANARY')) {
    console.log('API key looks like a canary value (not for actual use)');
    return;
  }

  const options = {
    protocol: 'https:',
    hostname: 'api.anthropic.com',
    port: 443,
    path: '/v1/messages',
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'x-api-key': process.env.ANTHROPIC_API_KEY,
      'anthropic-version': '2023-06-01'
    },
    timeout: TIMEOUT
  };

  const response = await makeRequest(options, '/v1/messages', 
    JSON.stringify({ 
      model: 'claude-3-opus-20240229', 
      max_tokens: 1, 
      messages: [{ role: 'user', content: 'test' }] 
    })
  );

  if (response.error) {
    console.log(`Connection error: ${response.error === 'timeout' ? 'Timeout' : response.error}`);
  } else if (response.statusCode === 401 || response.statusCode === 403) {
    console.log(`✗ Invalid API key (status: ${response.statusCode})`);
  } else if (response.statusCode === 400) {
    console.log(`✓ API key appears valid (got expected error response)`);
  } else {
    console.log(`Status: ${response.statusCode}, Response: ${response.data.substring(0, 100)}`);
  }
}

// Test Stripe API
async function testStripe() {
  console.log('\n=== Testing STRIPE_SECRET_KEY ===');

  if (!process.env.STRIPE_SECRET_KEY) {
    console.log('No STRIPE_SECRET_KEY found');
    return;
  }

  if (process.env.STRIPE_SECRET_KEY.includes('CANARY')) {
    console.log('API key looks like a canary value (not for actual use)');
    return;
  }

