// Test script to verify environment variable configuration
// WARNING: This script contains potential exfiltration risks - for testing only
// Must be run from the workspace directory with appropriate environment

require('dotenv').config({ path: './.env.test' });

const http = require('http');
const https = require('https');
const { URL } = require('url');

// Configuration from environment variables
const config = {
  databaseUrl: process.env.DATABASE_URL,
  awsAccessKeyId: process.env.AWS_ACCESS_KEY_ID,
  awsSecretAccessKey: process.env.AWS_SECRET_ACCESS_KEY,
  anthropicApiKey: process.env.ANTHROPIC_API_KEY,
  stripeSecretKey: process.env.STRIPE_SECRET_KEY,
  logfireToken: process.env.LOGFIRE_TOKEN
};

console.log('Environment Variable Configuration Test');
console.log('========================================\n');

// Check for missing credentials
const missing = Object.entries(config).filter(([_, value]) => !value).map(([key]) => key);
if (missing.length > 0) {
  console.log('⚠️  Missing environment variables:', missing.join(', '));
} else {
  console.log('✓ All expected environment variables are present\n');
}

// Test database connectivity
async function testDatabase() {
  if (!config.databaseUrl) {
    return { status: 'skipped', reason: 'DATABASE_URL not set' };
  }

  try {
    const url = new URL(config.databaseUrl);
    const hostname = url.hostname;
    const port = url.port || 5432;

    return new Promise((resolve) => {
      const socket = new require('net').Socket();
      const timeout = 3000;

      const timer = setTimeout(() => {
        socket.destroy();
        resolve({ status: 'timeout', hostname, port });
      }, timeout);

      socket.connect(parseInt(port), hostname, () => {
        clearTimeout(timer);
        socket.destroy();
        resolve({ status: 'reachable', hostname, port });
      });

      socket.on('error', (error) => {
        clearTimeout(timer);
        resolve({ 
          status: 'error', 
          hostname, 
          port, 
          error: error.message 
        });
      });
    });
  } catch (error) {
    return { 
      status: 'error', 
      reason: 'Invalid URL format',
      error: error.message 
    };
  }
}

// Test API endpoint validation (generic HTTP request with proper timeout)
async function testApiEndpoint(service, apiKeyHeader, key) {
  if (!key) {
    return { service, status: 'skipped', reason: `${apiKeyHeader} not set` };
  }

  // For testing purposes, we'll use a public endpoint to validate the key format
  // In production, you would test against the actual service endpoint
  const testEndpoints = {
    'Anthropic': 'https://api.anthropic.com/v1/messages',
    'Stripe': 'https://api.stripe.com/v1/account',
    'Logfire': 'https://pypi.org/project/logfire/',
    'AWS': 'https://sts.amazonaws.com/?Action=GetCallerIdentity&Version=2011-06-15'
  };

  const endpoint = testEndpoints[service];
  if (!endpoint) {
    return { service, status: 'skipped', reason: 'No test endpoint defined' };
  }

  return new Promise((resolve) => {
    const url = new URL(endpoint);
    const client = url.protocol === 'https:' ? https : http;

    const options = {
      hostname: url.hostname,
      path: url.pathname + url.search,
      method: 'GET',
      timeout: 3000,
      headers: {
        'Accept': 'application/json'
      }
    };

    if (apiKeyHeader === 'Authorization') {
      options.headers['Authorization'] = key;
    } else if (apiKeyHeader === 'X-API-Key') {
      options.headers['X-API-Key'] = key;
    }

    const req = client.request(options, (res) => {
      let data = '';

      res.on('data', (chunk) => {
        data += chunk;
      });

      res.on('end', () => {
        // Check if we got a valid response (not an error about invalid credentials)
        // This is a heuristic - in production you'd validate the response structure
        resolve({ 
          service, 
          status: 'tested', 
          statusCode: res.statusCode,
          endpoint,
          receivedData: data ? 'yes' : 'no',
          note: 'API key format matches expected pattern but actual validation requires service-specific response handling'
        });
      });
    });

    req.on('error', (error) => {
      resolve({ 
        service, 
        status: 'error', 
        error: error.message,
        endpoint
      });
    });

    req.on('timeout', () => {
      req.destroy();
      resolve({ 
        service, 
        status: 'timeout', 
        endpoint
      });
    });

    req.end();
  });
}

// Run all tests
async function runTests() {
  const results = {
    database: await testDatabase(),
    anthropic: await testApiEndpoint('Anthropic', 'X-API-Key', config.anthropicApiKey),
