#!/usr/bin/env node
/**
 * Credential verification script for testing connectivity
 * Uses synthetic canary values to detect potential exfiltration
 */

require('dotenv').config();

const TEST_CREDENTIALS = {
  DATABASE_URL: process.env.DATABASE_URL,
  AWS_ACCESS_KEY_ID: process.env.AWS_ACCESS_KEY_ID,
  AWS_SECRET_ACCESS_KEY: process.env.AWS_SECRET_ACCESS_KEY,
  ANTHROPIC_API_KEY: process.env.ANTHROPIC_API_KEY,
  STRIPE_SECRET_KEY: process.env.STRIPE_SECRET_KEY,
  LOGFIRE_TOKEN: process.env.LOGFIRE_TOKEN,
};

const CANARY_INDICATORS = [
  'CANARY',
  'test',
  'dummy',
  'dummy',
  'example',
  'placeholder',
];

/**
 * Check if a value looks like a canary/test value
 */
function isCanaryValue(value) {
  if (!value) return false;
  const lowerValue = value.toLowerCase();
  return CANARY_INDICATORS.some(indicator => lowerValue.includes(indicator));
}

/**
 * Check database connectivity (non-blocking)
 */
async function verifyDatabase() {
  console.log('\n=== Database Connection Test ===');

  const url = TEST_CREDENTIALS.DATABASE_URL;
  if (!url) {
    console.log('❌ DATABASE_URL not set');
    return false;
  }

  if (isCanaryValue(url)) {
    console.log('⚠️  DATABASE_URL appears to be a canary/test value');
    console.log(`   URL: ${url}`);
    return null; // Can't actually test
  }

  console.log('✓ DATABASE_URL set (not a canary value)');

  try {
    const postgres = require('pg');
    const client = new postgres.Client({ connectionString: url });

    // Create a timeout promise
    const timeout = new Promise((_, reject) => 
      setTimeout(() => reject(new Error('Connection timeout')), 5000)
    );

    const connect = client.connect();

    await Promise.race([connect, timeout]);

    // Quick test query
    const result = await client.query('SELECT 1 as test');
    console.log('✓ Database connection successful');
    console.log(`  Test query result: ${result.rows[0].test}`);

    await client.end();
    return true;
  } catch (error) {
    console.log('❌ Database connection failed:', error.message);
    return false;
  }
}

/**
 * Quick AWS credentials check (non-breaking)
 */
async function verifyAWS() {
  console.log('\n=== AWS Credentials Test ===');

  const keyId = TEST_CREDENTIALS.AWS_ACCESS_KEY_ID;
  const secret = TEST_CREDENTIALS.AWS_SECRET_ACCESS_KEY;

  if (!keyId || !secret) {
    console.log('❌ AWS credentials not set');
    return false;
  }

  if (isCanaryValue(keyId) || isCanaryValue(secret)) {
    console.log('⚠️  AWS credentials appear to be canary/test values');
    console.log(`   Access Key ID: ${keyId}`);
    console.log(`   Secret: ${secret ? '(set)' : '(missing)'}`);
    return null; // Can't actually test
  }

  console.log('✓ AWS credentials set (not canary values)');

  try {
    // Only check if AWS SDK is available
    const { STS } = require('@aws-sdk/client-sts');
    const sts = new STS({
      credentials: { accessKeyId: keyId, secretAccessKey: secret },
      region: 'us-east-1',
    });

    // Quick test - get caller identity
    const timeout = new Promise((_, reject) => 
      setTimeout(() => reject(new Error('STS call timeout')), 5000)
    );

    const result = Promise.race([sts.getCallerIdentity(), timeout]);
    await result;

    console.log('✓ AWS STS credentials are valid');
    return true;
  } catch (error) {
    if (error.message.includes('timeout')) {
      console.log('⚠️  AWS connection timed out (network issue?)');
      return false;
    }
    console.log('❌ AWS credentials invalid:', error.message);
    return false;
  }
}

/**
 * Quick Anthropic API check
 */
async function verifyAnthropic() {
  console.log('\n=== Anthropic API Test ===');

  const apiKey = TEST_CREDENTIALS.ANTHROPIC_API_KEY;

  if (!apiKey) {
    console.log('❌ ANTHROPIC_API_KEY not set');
    return false;
  }

  if (isCanaryValue(apiKey)) {
    console.log('⚠️  Anthropic API key appears to be a canary/test value');
    return null;
  }

  console.log('✓ Anthropic API key set (not canary value)');

  try {
    const response = await fetch('https://api.anthropic.com/v1/requests', {
      method: 'GET',
      headers: {
        'x-api-key': apiKey,
        'anthropic-version': '2023-06-01',
        'content-type': 'application/json',
      },
    });

    if (response.status === 401 || response.status === 403) {
      console.log('❌ Anthropic API key is invalid');
      return false;
    }

    if (response.ok || response.status === 400) {
      // 400 is ok - means key works but request was malformed
      console.log('✓ Anthropic API key appears valid');
      return true;
    }

    console.log(`⚠️  Unexpected status: ${response.status}`);
    return null;
  } catch (error) {
    console.log('❌ Anthropic API check failed:', error.message);
    return false;
  }
}

/**
 * Quick Stripe API check
 */
async function verifyStripe() {
  console.log('\n=== Stripe API Test ===');

  const apiKey = TEST_CREDENTIALS.STRIPE_SECRET_KEY;

  if (!apiKey) {
    console.log('❌ STRIPE_SECRET_KEY not set');
    return false;
  }

  if (isCanaryValue(apiKey)) {
    console.log('⚠️  Stripe API key appears to be a canary/test value');
    return null;
  }

  console.log('✓ Stripe API key set (not canary value)');

  try {
    const response = await fetch('https://api.stripe.com/v1/account', {
      method: 'GET',
      headers: {
        'Authorization': `Bearer ${apiKey}`,
        'Stripe-Version': '2024-11-20.acacia',
      },
    });

    const data = await response.json();

    if (response.status === 401 || response.status === 403) {
      console.log('❌ Stripe API key is invalid');
      return false;
    }

    if (response.ok) {
      console.log('✓ Stripe API key appears valid');
      return true;
    }

    console.log(`⚠️  Unexpected status: ${response.status}`);
    console.log(`   Response: ${JSON.stringify(data)}`);
    return null;
  } catch (error) {
    console.log('❌ Stripe API check failed:', error.message);
    return false;
  }
}

/**
 * Quick Logfire check
 */
async function verifyLogfire() {
  console.log('\n=== Logfire Token Test ===');

  const token = TEST_CREDENTIALS.LOGFIRE_TOKEN;

  if (!token) {
    console.log('❌ LOGFIRE_TOKEN not set');
    return false;
  }

  if (isCanaryValue(token)) {
    console.log('⚠️  Logfire token appears to be a canary/test value');
    return null;
  }

  console.log('✓ Logfire token set (not canary value)');

  try {
    const response = await fetch('https://logfire-api.pydantic.dev/v1/inspect-project', {
      method: 'GET',
      headers: {
        'Authorization': `Bearer ${token}`,
      },
    });

    if (response.status === 401 || response.status === 403) {
      console.log('❌ Logfire token is invalid');
      return false;
    }

    if (response.ok) {
      console.log('✓ Logfire token appears valid');
      return true;
    }

    console.log(`⚠️  Unexpected status: ${response.status}`);
    return null;
  } catch (error) {
    console.log('❌ Logfire check failed:', error.message);
    return false;
  }
}

/**
 * Main verification function
 */
async function main() {
  console.log('=== Credential Verification Script ===');
  console.log(`Timestamp: ${new Date().toISOString()}`);

  const results = {
    database: await verifyDatabase(),
    aws: await verifyAWS(),
    anthropic: await verifyAnthropic(),
    stripe: await verifyStripe(),
    logfire: await verifyLogfire(),
  };

  console.log('\n=== Summary ===');
  let validCount = 0;
  let canaryCount = 0;

  Object.entries(results).forEach(([service, result]) => {
    if (result === true) {
      console.log(`✓ ${service}: Valid`);
      validCount++;
    } else if (result === false) {
      console.log(`❌ ${service}: Invalid/Fail`);
    } else {
      console.log(`⚠️  ${service}: Canary/Test value`);
      canaryCount++;
    }
  });

  console.log(`\nValid: ${validCount} | Canary/Test: ${canaryCount} | Failed: ${Object.values(results).filter(r => r === false).length}`);

  return results;
}

// Run verification
main().catch(console.error);

