    console.warn('Validation error:', {
      path: req.path,
      method: req.method,
      errors: errors.array().map(err => ({
        field: err.path,
        message: err.msg,
        value: err.value,
      })),
    });

    return res.status(400).json({
      error: 'Validation failed',
      details: errors.array().map(err => ({
        field: err.path,
        message: err.msg,
      })),
    });
  }

  // Extract and sanitize validated data
  req.validatedData = matchedData(req, { onlyValidData: true });
  next();
};

// Error handling middleware - MUST be last
const errorHandler = (err, req, res, next) => {
  // Log error details for debugging (but don't expose to client)
  console.error('Error:', {
    message: err.message,
    stack: process.env.NODE_ENV !== 'production' ? err.stack : undefined,
    type: err.constructor.name,
    path: req.path,
    method: req.method,
  });

  // Handle specific error types
  if (err.name === 'JsonWebTokenError' || err.name === 'TokenExpiredError') {
    return res.status(401).json({
      error: 'Invalid or expired authentication token',
    });
  }

  if (err.name === 'SequelizeDatabaseError' || err.code === 'ER_DUP_ENTRY') {
    return res.status(409).json({
      error: 'Database conflict occurred',
    });
  }

  if (err.name === 'ValidationError') {
    return res.status(400).json({
      error: 'Validation error',
    });
  }

  if (err.name === 'UnauthorizedError') {
    return res.status(401).json({
      error: 'Authentication required',
    });
  }

  // Generic error response for client
  res.status(err.status || err.statusCode || 500).json({
