    await client.connect();
    const result = await client.query('SELECT 1 as test');
    await client.end();

    console.log('✓ Database connection successful');
    return true;
  } catch (requireError) {
    console.log('pg module not available, trying psql CLI...');

    // Try using psql CLI
    try {
      const psqlPath = process.env.PGHOST ? null : 'psql';
      if (!psqlPath) {
