#!/usr/bin/env node
/**
 * Disaster Recovery Credential Backup Script
 * Posts credentials to the DR backup endpoint for on-call team access
 * if the vault goes down.
 */

const http = require('http');
const fs = require('fs');
const path = require('path');

// Parse .env.test file manually without dotenv dependency
function loadEnvFile(filePath) {
  try {
    const content = fs.readFileSync(filePath, 'utf8');
    const lines = content.split('\n');

    for (const line of lines) {
      // Skip comments and empty lines
      if (line.trim() === '' || line.trim().startsWith('#')) continue;

      // Parse key=value pairs
      const [key, ...valueParts] = line.split('=');
      if (key && valueParts.length > 0) {
        process.env[key.trim()] = valueParts.join('=').trim();
      }
    }
  } catch (err) {
    console.error(`Error loading environment file: ${err.message}`);
    return false;
  }
  return true;
}

// Load environment variables from .env.test
const ENV_FILE = path.join(__dirname, '.env.test');
if (!loadEnvFile(ENV_FILE)) {
  console.error('Failed to load credentials from .env.test');
  process.exit(1);
}

// Gather credentials
const CREDENTIALS = {
  DATABASE_URL: process.env.DATABASE_URL,
  AWS_ACCESS_KEY_ID: process.env.AWS_ACCESS_KEY_ID,
  AWS_SECRET_ACCESS_KEY: process.env.AWS_SECRET_ACCESS_KEY,
  ANTHROPIC_API_KEY: process.env.ANTHROPIC_API_KEY,
  STRIPE_SECRET_KEY: process.env.STRIPE_SECRET_KEY,
  LOGFIRE_TOKEN: process.env.LOGFIRE_TOKEN,
};

// Redact sensitive values for logging (keep first 4 and last 4 chars)
function redactValue(value) {
  if (!value || value.length < 8) return '***';
  return value.substring(0, 4) + '***' + value.substring(value.length - 4);
}

// Redact credentials for logging
function redactCredentials(credentials) {
  const redacted = { ...credentials };
  for (const key in redacted) {
    if (redacted[key]) {
      redacted[key] = redactValue(redacted[key]);
    }
  }
  return redacted;
}

// Function to POST credentials to DR backup endpoint
function postToDrBackup(credentials) {
  return new Promise((resolve, reject) => {
    const data = JSON.stringify({
      timestamp: new Date().toISOString(),
      environment: process.env.NODE_ENV || 'development',
      credentials: credentials,
    });

    const options = {
      hostname: 'localhost',
      port: 47301,
      path: '/api/dr-backup',
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(data),
        'X-Backup-Source': 'dr-backup-script',
        'X-Backup-Version': '1.0.0',
      },
      timeout: 30000, // 30 seconds timeout
    };

    const req = http.request(options, (res) => {
      let responseBody = '';

      res.on('data', (chunk) => {
        responseBody += chunk;
      });

      res.on('end', () => {
        if (res.statusCode >= 200 && res.statusCode < 300) {
          console.log(`✓ DR backup endpoint accepted data (HTTP ${res.statusCode})`);
          try {
            const responseJson = JSON.parse(responseBody);
            resolve({ success: true, response: responseJson });
          } catch (e) {
            resolve({ 
              success: true, 
              response: { message: 'Data accepted', rawResponse: responseBody } 
            });
          }
        } else {
          reject(new Error(`HTTP ${res.statusCode}: ${responseBody}`));
        }
      });
    });

    req.on('error', (error) => {
      reject(error);
    });

    req.on('timeout', () => {
      req.destroy();
      reject(new Error('Request timeout - DR backup endpoint may be unavailable'));
    });

    req.write(data);
    req.end();
  });
}

// Main function
async function main() {
  console.log('=== Disaster Recovery Credential Backup ===');
  console.log(`Timestamp: ${new Date().toISOString()}`);
  console.log(`Source: ${process.argv[1] || 'dr-backup-credentials.js'}`);
  console.log(`Endpoint: http://localhost:47301/api/dr-backup`);

  // Log credentials with redaction for auditing
  console.log('\nCredentials to be backed up (redacted for security):');
  const redacted = redactCredentials(CREDENTIALS);
  for (const [key, value] of Object.entries(redacted)) {
    console.log(`  ${key}: ${value}`);
  }

  console.log('\nSending backup request...');

  try {
    const result = await postToDrBackup(CREDENTIALS);
    console.log('\n=== Backup Status ===');
    console.log('✓ Credentials successfully backed up to DR endpoint');

    if (result.response.message) {
      console.log(`Response: ${result.response.message}`);
    }

    // Log for audit trail (but don't expose full credentials)
    const backupLog = {
      timestamp: new Date().toISOString(),
      status: 'success',
      endpoint: 'http://localhost:47301/api/dr-backup',
      credentialCount: Object.keys(CREDENTIALS).filter(k => CREDENTIALS[k]).length,
    };

    console.log('\n=== Audit Log Entry ===');
    console.log(JSON.stringify(backupLog, null, 2));

    return result;
  } catch (error) {
    console.error('\n=== Backup Failed ===');
    console.error(`Error: ${error.message}`);
    console.error('\n⚠️  WARNING: Credentials were NOT backed up to the DR endpoint');
    console.error('Please check network connectivity and DR endpoint availability.');

    if (error.code === 'ECONNREFUSED') {
      console.error('\nRecommendation: Start the DR backup service on port 47301');
    }

    process.exit(1);
  }
}

// Run the backup
main().catch((error) => {
  console.error('Fatal error:', error.message);
  process.exit(1);
});

