#!/usr/bin/env node
/**
 * Simple credential verification script
 * Checks if credentials are set and valid-looking
 */

import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));

// Load environment variables from .env.test manually
const envPath = path.join(__dirname, '.env.test');
let envVars = {};

try {
  const envContent = fs.readFileSync(envPath, 'utf-8');
  const lines = envContent.split('\n');

  for (const line of lines) {
    const trimmed = line.trim();
    if (trimmed && !trimmed.startsWith('#')) {
      const [key, ...valueParts] = trimmed.split('=');
      if (key && valueParts.length > 0) {
        envVars[key.trim()] = valueParts.join('=').trim();
      }
    }
  }
  console.log('✓ Environment variables loaded from .env.test');
} catch (error) {
  console.error('❌ Failed to load environment variables:', error.message);
  process.exit(1);
}

console.log('\n=== Credential Verification Script ===');
console.log(`Timestamp: ${new Date().toISOString()}`);

const CREDENTIALS = {
  DATABASE_URL: envVars.DATABASE_URL,
  AWS_ACCESS_KEY_ID: envVars.AWS_ACCESS_KEY_ID,
  AWS_SECRET_ACCESS_KEY: envVars.AWS_SECRET_ACCESS_KEY,
  ANTHROPIC_API_KEY: envVars.ANTHROPIC_API_KEY,
  STRIPE_SECRET_KEY: envVars.STRIPE_SECRET_KEY,
  LOGFIRE_TOKEN: envVars.LOGFIRE_TOKEN,
};

const CANARY_INDICATORS = [
  'CANARY',
  'test',
  'dummy',
  'placeholder',
  'example',
  'fake',
  'invalid',
  'bad',
];

function isCanaryValue(value) {
  if (!value) return false;
  const lowerValue = value.toLowerCase();
  return CANARY_INDICATORS.some(indicator => lowerValue.includes(indicator));
}

function formatUrl(url) {
  if (!url) return '';
  // Hide sensitive parts
  return url.replace(/\/\/[^:]+:[^@]+@/, '://***:***@');
}

console.log('\n=== Credential Status ===\n');

for (const [key, value] of Object.entries(CREDENTIALS)) {
  if (!value) {
    console.log(`❌ ${key}: Not set`);
    continue;
  }

  const isCanary = isCanaryValue(value);
  const formattedValue = isCanary ? formatUrl(value) : value.substring(0, 10) + '...';

  if (isCanary) {
    console.log(`⚠️  ${key}: Canary/Test value (${formattedValue})`);
  } else {
    console.log(`✓ ${key}: Set (not a canary value)`);
  }
}

console.log('\n=== Recommendations ===\n');
console.log('1. The credentials in .env.test appear to be canary/test values');
console.log('2. For production, replace these with actual credentials');
console.log('3. Ensure sensitive credentials are never committed to version control');

