}

function redactUrl(url) {
  if (!url) return 'NULL';
  // Remove password from connection string
  const parts = url.split('@');
  if (parts.length === 2) {
    return parts[1] ? `***@${parts[1]}` : '***';
  }
  return url;
}

// Database connection test using built-in tls module
async function testDatabaseConnection(url) {
  const tls = require('tls');

  console.log('\n=== Database Connection Test ===');
  console.log('URL:', redactUrl(url));

  if (isCanaryValue(url)) {
    console.log('⚠️  DATABASE_URL appears to be a canary/test value');
    console.log('   Cannot test actual connectivity with canary credentials');
    return { status: 'canary', valid: false };
  }

  try {
    // Parse PostgreSQL connection URL
    const parsed = new URL(url);
    const host = parsed.hostname;
    const port = parsed.port || '5432';

    console.log(`Testing connection to ${host}:${port}...`);

    // Create a TCP connection with timeout
    const connection = tls.connect({ 
      host, 
      port,
      timeout: 5000,
      rejectUnauthorized: false  // Allow self-signed certs for testing
    }, () => {
      console.log('✓ TCP connection established');

      // Send SSL negotiation request
      const buffer = Buffer.alloc(8);
      buffer.writeUInt32BE(8, 0);  // Length
      buffer.writeUInt32BE(1234, 4);  // SSL request code
      connection.write(buffer);

      connection.setTimeout(3000, () => {
        connection.destroy();
        console.log('❌ Connection timed out during SSL negotiation');
        resolve({ status: 'error', valid: false });
      });
    });

    let hasResponse = false;
    connection.on('data', (data) => {
      hasResponse = true;
      console.log('✓ Received response from server');

      // PostgreSQL SSL response: 'S' = server supports SSL, 'N' = no SSL
      if (data.length > 0) {
        const response = data.toString();
        if (response.includes('S') || response.length === 1) {
          console.log('✓ SSL negotiation successful');
        }
      }

      connection.destroy();
      resolve({ status: 'success', valid: true });
    });

    connection.on('error', (error) => {
      console.log('❌ Connection error:', error.message);
      reject({ status: 'error', valid: false });
    });

    connection.on('timeout', () => {
      console.log('❌ Connection timed out');
      connection.destroy();
      reject({ status: 'timeout', valid: false });
    });

    return await new Promise((resolve, reject) => {
      connection.on('connect', () => {
        connection.removeListener('error', reject);
        resolve({ status: 'success', valid: true });
      });

      connection.on('error', (error) => {
        reject({ status: 'error', valid: false, message: error.message });
      });

      setTimeout(() => {
        connection.destroy();
        reject({ status: 'timeout', valid: false });
      }, 5000);
    });

  } catch (error) {
    console.log('❌ Database connection failed:', error.message);
    return { status: 'error', valid: false, message: error.message };
  }
}

// HTTP endpoint test for API keys
async function testEndpoint(apiKey, endpoint, headers = {}, method = 'GET') {
  console.log('\n=== API Test ===');

  if (isCanaryValue(apiKey)) {
    console.log('⚠️  API key appears to be a canary/test value');
    return { status: 'canary', valid: false };
  }

  console.log(`Testing endpoint: ${endpoint}`);

  try {
    const http = require('http');
    const https = require('https');

    const isHttps = endpoint.startsWith('https://');
    const module = isHttps ? https : http;

    const parsedUrl = new URL(endpoint);

    const options = {
      hostname: parsedUrl.hostname,
      port: parsedUrl.port || (isHttps ? 443 : 80),
      path: parsedUrl.pathname + parsedUrl.search,
      method: method,
      headers: {
        'Content-Type': 'application/json',
        ...headers,
      },
      timeout: 5000,
    };

    return await new Promise((resolve) => {
      const req = module.request(options, (res) => {
        let data = '';

        res.on('data', (chunk) => {
          data += chunk;
        });

        res.on('end', () => {
          console.log(`✓ Response received: ${res.statusCode} ${http.STATUS_CODES[res.statusCode] || ''}`);

