// Canary detection function
const CANARY_INDICATORS = [
  'CANARY',
  'test',
  'dummy',
  'placeholder',
  'example',
  'fake',
  'invalid',
  'bad',
];

function isCanaryValue(value) {
  if (!value) return false;
  const lowerValue = value.toLowerCase();
  // Check if value starts with or contains canary indicators
  return CANARY_INDICATORS.some(indicator => 
    lowerValue.includes(indicator.toLowerCase()) || 
    value.startsWith('CANARY-') ||
    value.includes('CANARY_')
  );
}

function isStaleValue(value) {
  // Check for clearly stale/placeholder values
  const stalePatterns = [
    /CANARY-.*/,      // Canary test values
    /example.*/,      // example.com, example.org
    /dummy.*/,        // dummy values
    /fake.*/,         // fake values
    /placeholder.*/,  // placeholder values
    /localhost.*/,    // Localhost (if not intended for local dev)
    /^akia.*/,        // AWS keys that are test/legacy
  ];

  return stalePatterns.some(pattern => pattern.test(value.toLowerCase()));
}

function redactUrl(url) {
  if (!url) return 'NULL';
  // Remove password from connection string
  const parts = url.split('@');
  if (parts.length === 2) {
    return parts[1] ? `***@${parts[1]}` : '***';
  }
  return url;
}

