#!/usr/bin/env node
/**
 * Simple credential verification script
 * Tests if credentials from .env.test are still valid
 */
import { readFileSync } from 'fs';
import { exec } from 'child_process';
import { promises as fs } from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

// Read .env.test file manually to extract values
const envPath = path.join(__dirname, '.env.test');
let envContent = '';
try {
  envContent = await fs.readFile(envPath, 'utf8');
} catch (err) {
  console.error(`Error reading .env.test: ${err.message}`);
  process.exit(1);
}

// Parse environment variables from .env.test
const envVars = {};
const lines = envContent.split('\n');
for (const line of lines) {
  const trimmed = line.trim();
  if (trimmed && !trimmed.startsWith('#') && trimmed.includes('=')) {
    const [key, ...valueParts] = trimmed.split('=');
    envVars[key.trim()] = valueParts.join('=').trim();
  }
}

console.log('=== Credential Verification Test ===');
console.log(`Timestamp: ${new Date().toISOString()}`);
console.log(`Checking credentials from: ${envPath}`);
console.log('');

let results = {
  database: { status: 'not_tested', message: '' },
  aws: { status: 'not_tested', message: '' },
  anthropic: { status: 'not_tested', message: '' },
  stripe: { status: 'not_tested', message: '' },
  logfire: { status: 'not_tested', message: '' }
};

// Check for canary/test indicators
function isCanaryValue(value) {
  if (!value) return true;
  const lower = value.toLowerCase();
  const canaryIndicators = ['canary', 'test', 'dummy', 'placeholder', 'example', 'fake', 'invalid'];
  return canaryIndicators.some(ind => lower.includes(ind));
}

// Test 1: Database Connection
async function testDatabase() {
  const url = envVars.DATABASE_URL;

  if (!url) {
    results.database = { status: 'error', message: 'DATABASE_URL not set' };
    return;
  }

  if (isCanaryValue(url)) {
    results.database = { status: 'canary', message: 'Credential appears to be a test value' };
    return;
  }

  // Try using psql if available
  console.log('Testing database connection...');
  const promisifiedExec = (cmd, args) => {
    return new Promise((resolve) => {
      const child = exec(`${cmd} ${args}`, (error, stdout, stderr) => {
        resolve({ error, stdout, stderr });
      });
      // Set timeout
      setTimeout(() => {
        child.kill('SIGTERM');
        resolve({ timeout: true });
      }, 5000);
    });
  };

  try {
    const result = await promisifiedExec('psql', `${url} -c "SELECT 1" 2>&1`);
    if (result.timeout) {
      results.database = { status: 'timeout', message: 'Connection timed out' };
    } else if (result.stdout && (result.stdout.includes('1 row') || result.stdout.includes('1'))) {
      results.database = { status: 'valid', message: 'Database connection successful' };
    } else {
      results.database = { status: 'invalid', message: result.stderr || result.error?.message || 'Connection failed' };
    }
  } catch (err) {
    results.database = { status: 'error', message: err.message };
  }
}

// Test 2: AWS Credentials (mock check)
async function testAWS() {
