  const secret = envVars.AWS_SECRET_ACCESS_KEY;

  if (!keyId || !secret) {
    results.aws = { status: 'error', message: 'AWS credentials not set' };
    return;
  }

  if (isCanaryValue(keyId) || isCanaryValue(secret)) {
    results.aws = { status: 'canary', message: 'AWS credentials appear to be test values' };
    return;
  }

  // For testing, we'll check key format and make a mock request
  const isValidFormat = keyId.startsWith('AKIA') && secret.length > 20;
  if (isValidFormat) {
