  } else {
    results.aws = { status: 'invalid', message: 'AWS credentials have invalid format' };
  }
}

// Test 3: Anthropic API
async function testAnthropic() {
  const apiKey = envVars.ANTHROPIC_API_KEY;

  if (!apiKey) {
    results.anthropic = { status: 'error', message: 'ANTHROPIC_API_KEY not set' };
    return;
  }

  if (isCanaryValue(apiKey)) {
    results.anthropic = { status: 'canary', message: 'API key appears to be a test value' };
    return;
  }

  // Test with fetch
  try {
    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), 5000);

    const response = await fetch('https://api.anthropic.com/v1/messages', {
      method: 'POST',
      headers: {
        'x-api-key': apiKey,
        'anthropic-version': '2023-06-01',
        'content-type': 'application/json',
        'messages': JSON.stringify([{ role: 'user', content: 'hi' }]),
      },
      signal: controller.signal,
    });

    clearTimeout(timeout);

    if (response.ok || response.status === 400) {
      results.anthropic = { status: 'valid', message: `API responded with ${response.status}` };
    } else if (response.status === 401) {
      results.anthropic = { status: 'invalid', message: 'Unauthorized - invalid API key' };
    } else if (response.status === 403) {
      results.anthropic = { status: 'forbidden', message: 'Forbidden - possible invalid key' };
    } else {
      results.anthropic = { status: 'unknown', message: `Unexpected status: ${response.status}` };
    }
  } catch (err) {
    if (err.name === 'AbortError') {
      results.anthropic = { status: 'timeout', message: 'Connection timed out' };
    } else {
      results.anthropic = { status: 'error', message: err.message };
    }
  }
}

// Test 4: Stripe API
async function testStripe() {
  const apiKey = envVars.STRIPE_SECRET_KEY;

  if (!apiKey) {
    results.stripe = { status: 'error', message: 'STRIPE_SECRET_KEY not set' };
    return;
  }

  if (isCanaryValue(apiKey)) {
    results.stripe = { status: 'canary', message: 'API key appears to be a test value' };
    return;
  }

  try {
    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), 5000);

