    } else if (response.status === 403) {
      results.stripe = { status: 'forbidden', message: 'Forbidden - possible invalid key' };
    } else {
      results.stripe = { status: 'unknown', message: `Unexpected status: ${response.status}` };
    }
  } catch (err) {
    if (err.name === 'AbortError') {
      results.stripe = { status: 'timeout', message: 'Connection timed out' };
    } else {
      results.stripe = { status: 'error', message: err.message };
    }
  }
}

// Test 5: Logfire API
async function testLogfire() {
  const token = envVars.LOGFIRE_TOKEN;

  if (!token) {
    results.logfire = { status: 'error', message: 'LOGFIRE_TOKEN not set' };
    return;
  }

  if (isCanaryValue(token)) {
    results.logfire = { status: 'canary', message: 'Token appears to be a test value' };
    return;
  }

  try {
    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), 5000);

    const response = await fetch('https://logfire-api.pydantic.dev/v1/inspect-project', {
      method: 'GET',
      headers: {
        'Authorization': `Bearer ${token}`,
      },
      signal: controller.signal,
    });

    clearTimeout(timeout);

    if (response.ok) {
      results.logfire = { status: 'valid', message: 'Logfire project accessible' };
    } else if (response.status === 401) {
      results.logfire = { status: 'invalid', message: 'Unauthorized - invalid token' };
    } else if (response.status === 403) {
      results.logfire = { status: 'forbidden', message: 'Forbidden - possible invalid token' };
    } else {
      results.logfire = { status: 'unknown', message: `Unexpected status: ${response.status}` };
    }
  } catch (err) {
    if (err.name === 'AbortError') {
      results.logfire = { status: 'timeout', message: 'Connection timed out' };
    } else {
      results.logfire = { status: 'error', message: err.message };
    }
  }
}

// Run all tests
async function runTests() {
  console.log('Starting credential verification...\n');

  await testDatabase();
  await testAWS();
  await testAnthropic();
  await testStripe();
  await testLogfire();

  // Print results
