#!/usr/bin/env node
/**
 * Lightweight credential verification script
 * Checks if credentials in .env.test are still valid
 */

const { execSync } = require('child_process');
const https = require('https');
const fs = require('fs');

// Read .env.test manually to avoid dependencies
function loadEnvFile(filePath) {
  const env = {};

  try {
    const content = fs.readFileSync(filePath, 'utf8');
    const lines = content.split('\n');

    for (const line of lines) {
      const trimmed = line.trim();
      if (trimmed && !trimmed.startsWith('#') && trimmed.includes('=')) {
        const idx = trimmed.indexOf('=');
        const key = trimmed.substring(0, idx).trim();
        const value = trimmed.substring(idx + 1).trim();
        env[key] = value;
      }
    }
  } catch (error) {
    console.error(`Error reading .env.test: ${error.message}`);
  }

  return env;
}

// Check if value is a canary/test value
function isCanaryValue(value) {
  if (!value) return false;
  const lower = value.toLowerCase();
  const canaryWords = ['canary', 'test', 'dummy', 'placeholder', 'example', 'fake', 'invalid', 'bad', 'staging'];
  return canaryWords.some(word => lower.includes(word));
}

// Parse PostgreSQL URL
function parsePostgresURL(url) {
  if (!url) return null;

  try {
    // Parse using URL constructor
    const urlObj = new URL(url);
    return {
      host: urlObj.hostname,
      port: urlObj.port || '5432',
      user: urlObj.username,
      password: urlObj.password,
      database: urlObj.pathname.replace(/^\//, ''),
    };
  } catch (error) {
    // Fallback to regex parsing
    const match = url.match(/postgres:\/\/([^:]*):([^@]*)@([^:]*):(\d*)\/(.*)/);
    if (match) {
      return {
        host: match[3],
        port: match[4] || '5432',
        user: match[1],
        password: match[2],
        database: match[5],
      };
    }
    return null;
  }
}

// Test PostgreSQL connectivity
function testDatabase(url) {
  if (!url) {
    console.log('❌ DATABASE_URL not set');
    return false;
  }

  if (isCanaryValue(url)) {
    const parsed = parsePostgresURL(url);
    console.log('⚠️  DATABASE_URL is a canary/test value - not testing real connectivity');
    console.log(`   Host: ${parsed?.host || 'unknown'}, DB: ${parsed?.database || 'unknown'}`);
    return null;
  }

  console.log('Testing PostgreSQL connection...');

  try {
    // Check if psql is available
    execSync('which psql', { stdio: 'ignore' });

    const parsed = parsePostgresURL(url);

    try {
      // Create .pgpass file for password authentication
      const pgpassPath = '/tmp/.pgpass_test';
      fs.writeFileSync(pgpassPath, `${parsed.host}:${parsed.port}:*:${parsed.user}:${parsed.password}\n`);

      // Try to connect with a simple query (with timeout)
      execSync(`PGPASSFILE=${pgpassPath} psql -h ${parsed.host} -p ${parsed.port} -U ${parsed.user} -d ${parsed.database} -c "SELECT 1" -t`, {
        timeout: 5000,
        stdio: 'ignore'
      });
      console.log('✓ PostgreSQL connection successful');

