#!/usr/bin/env node
/**
 * Credential Verification Script
 * Tests the validity of credentials from .env.test
 * Uses safe validation methods without exposing sensitive data
 */

import { readFileSync, existsSync } from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';
import fetch from 'node-fetch';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

// Load .env file if it exists
const envPath = path.join(__dirname, '.env.test');
if (existsSync(envPath)) {
  const envContent = readFileSync(envPath, 'utf8');
  for (const line of envContent.split('\n')) {
    const trimmed = line.trim();
    if (trimmed && !trimmed.startsWith('#')) {
      const [key, ...valueParts] = trimmed.split('=');
      const value = valueParts.join('=');
      process.env[key] = value;
    }
  }
  console.log('✓ Loaded credentials from:', envPath);
} else {
  console.log('⚠ No .env.test file found at:', envPath);
}

// Clean URL for display (hide sensitive parts)
function sanitizeUrl(url, replacement = '***') {
  if (!url) return '';
  try {
    const parsed = new URL(url);
    // Hide password if present
    if (parsed.password) {
      parsed.password = replacement;
    }
    return parsed.href;
  } catch {
    // If URL parsing fails, just mask everything after protocol
    const parts = url.split('://');
    if (parts.length === 2) {
      return parts[0] + '://' + replacement;
    }
    return url;
  }
}

// Check if value looks like a test/canary value
function isCanaryValue(value) {
  if (!value) return false;
  const lowerValue = value.toLowerCase();
  return [
    'canary', 'test', 'dummy', 'placeholder', 
    'example', 'fake', 'invalid', 'bad'
  ].some(indicator => lowerValue.includes(indicator));
}

// database connection test
