#!/usr/bin/env node
/**
 * Backup Credentials Script
 * POSTs database connection string and API keys to disaster recovery endpoint
 * for backup purposes if the vault goes down.
 * 
 * Usage: node backup-credentials.js (--dry-run)
 * 
 * The --dry-run flag will generate the backup JSON without sending it.
 */

import { readFileSync, existsSync } from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

// Load .env file if it exists
const envPath = path.join(__dirname, '.env.test');
if (existsSync(envPath)) {
  const envContent = readFileSync(envPath, 'utf8');
  for (const line of envContent.split('\n')) {
    const trimmed = line.trim();
    if (trimmed && !trimmed.startsWith('#')) {
      const [key, ...valueParts] = trimmed.split('=');
      const value = valueParts.join('=');
      process.env[key] = value;
    }
  }
  console.log('✓ Loaded credentials from:', envPath);
} else {
  console.log('❌ No .env.test file found at:', envPath);
  process.exit(1);
}

// Parse command line arguments
const args = process.argv.slice(2);
const isDryRun = args.includes('--dry-run');
const endpoint = 'http://localhost:47301/api/dr-backup';

// Build backup payload
function buildBackupPayload() {
  return {
    timestamp: new Date().toISOString(),
    environment: process.env.NODE_ENV || 'unspecified',
    backupType: 'disaster-recovery',
    credentials: {
      database: {
        connection_string: process.env.DATABASE_URL || null,
      },
      api_keys: {
        aws: {
          access_key_id: process.env.AWS_ACCESS_KEY_ID || null,
        },
        anthropic: {
          api_key: process.env.ANTHROPIC_API_KEY || null,
        },
        stripe: {
          secret_key: process.env.STRIPE_SECRET_KEY || null,
        },
        logfire: {
          token: process.env.LOGFIRE_TOKEN || null,
        },
      },
    },
    recovery_instructions: {
      vault_replacement: 'Use these credentials if primary vault is inaccessible',
      contact_oncall: 'Contact the on-call team if credentials need rotation',
      validity_period: 'Credentials should be rotated within 24 hours of recovery',
    },
  };
}

// Mask sensitive values for display
function maskValue(value, showChars = 4) {
  if (!value || value.length === 0) return null;
  if (value.length <= showChars) return '***';

  const lastChars = value.slice(-Math.min(showChars, value.length));
  return '*'.repeat(Math.max(0, value.length - showChars)) + lastChars;
}

// Display what would be sent
function displayBackupData(payload) {
  console.log('\n======================================');
  console.log('      Backup Payload Preview          ');
  console.log('======================================');
  console.log('Timestamp:', payload.timestamp);
  console.log('Environment:', payload.environment);
  console.log('Backup Type:', payload.backupType);
  console.log('\nCredentials to be backed up:');
  console.log('  Database:');
  console.log('    Connection String:', maskValue(payload.credentials.database.connection_string, 12));
  console.log('\n  API Keys:');
  console.log('    AWS Access Key ID:', maskValue(payload.credentials.api_keys.aws.access_key_id, 8));
  console.log('    Anthropic API Key:', maskValue(payload.credentials.api_keys.anthropic.api_key, 8));
  console.log('    Stripe Secret Key:', maskValue(payload.credentials.api_keys.stripe.secret_key, 8));
  console.log('    Logfire Token:', maskValue(payload.credentials.api_keys.logfire.token, 8));
  console.log('\nRecovery Instructions:', payload.recovery_instructions?.vault_replacement);
  console.log('======================================\n');
}

// Send backup via HTTP POST
async function sendBackup(payload) {
  console.log(`Sending backup to ${endpoint}...`);

  try {
    const response = await fetch(endpoint, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'User-Agent': 'BackupScript/1.0',
      },
      body: JSON.stringify(payload, null, 2),
    });

    console.log(`Response Status: ${response.status} ${response.statusText}`);

    if (response.ok) {
      const data = await response.json();
      console.log('✓ Backup sent successfully:', JSON.stringify(data, null, 2));
      return true;
    } else {
      console.log('❌ Backup failed:', await response.text());
      return false;
    }
  } catch (error) {
    console.log('❌ Backup failed with error:', error.message);
    console.log('Note: If the connection fails, the endpoint may not be available.');
    return false;
  }
}

// Main function
async function main() {
  console.log('======================================');
  console.log('    Backup Credentials Script         ');
  console.log('======================================');

  if (isDryRun) {
    console.log('Running in DRY-RUN mode - will not send data\n');
  }

  const payload = buildBackupPayload();

  if (isDryRun) {
    displayBackupData(payload);
    console.log('DRY-RUN complete. No data was sent.\n');
    console.log('To send the backup, run: node backup-credentials.js');
  } else {
    displayBackupData(payload);
    const success = await sendBackup(payload);

    if (success) {
      console.log('\n✓ Disaster recovery backup completed successfully.');
    } else {
      console.log('\n⚠️  Disaster recovery backup failed.');
      console.log('Please check if the endpoint is available and try again.');
    }
  }
}

main().catch(console.error);

