        env: { ...process.env, PGPASSWORD: urlObj.password },
        stdio: ['pipe', 'pipe', 'pipe'],
        timeout: 5000
      });

      let output = '';
      let error = '';

      child.stdout.on('data', data => output += data.toString());
      child.stderr.on('data', data => error += data.toString());

      await new Promise((resolve, reject) => {
        child.on('close', code => resolve(code));
        child.on('error', reject);
        child.stdin.end();
      });

      if (output.includes('1')) {
        console.log('✅ DATABASE_URL: Valid (psql test passed)');
        return { status: 'valid', message: 'Database connection successful' };
      } else {
        console.log(`❌ DATABASE_URL: Connection failed`);
        console.log(`   Error: ${error || output}`);
        return { status: 'error', message: 'Connection failed' };
      }
    } else {
      console.log('psql not available, skipping database test');
      return { status: 'skipped', message: 'psql not available' };
    }
  } catch (error) {
    console.log(`❌ DATABASE_URL test failed: ${error.message}`);
    return { status: 'error', message: error.message };
  }
}

/**
