 */
async function testAWS() {
  console.log('\n=== Testing AWS Credentials ===');

  const keyId = process.env.AWS_ACCESS_KEY_ID;
  const secretKey = process.env.AWS_SECRET_ACCESS_KEY;

  if (!keyId || !secretKey) {
    console.log('❌ AWS credentials not set');
    return { status: 'error', message: 'Not set' };
  }

  if (isCanaryValue(keyId) || isCanaryValue(secretKey)) {
    console.log('⚠️  AWS credentials appear to be canary/test values');
    console.log(`   Access Key ID: ${keyId}`);
    return { status: 'canary', message: 'Test value' };
  }

  console.log('Testing AWS STS GetCallerIdentity...');

  try {
    // Try using AWS SDK v3 if available
    let stsClient, getCallerIdentityCommand;

    try {
      const awsClientSts = require('@aws-sdk/client-sts');
      stsClient = awsClientSts.STSClient;
      getCallerIdentityCommand = awsClientSts.GetCallerIdentityCommand;
    } catch (e) {
      try {
        const { STSClient, GetCallerIdentityCommand } = require('@aws-sdk/client-sts');
        stsClient = STSClient;
        getCallerIdentityCommand = GetCallerIdentityCommand;
      } catch (e2) {
        console.log('@aws-sdk/client-sts not available, skipping AWS test');
        return { status: 'skipped', message: 'AWS SDK not available' };
      }
    }

    const sts = new stsClient({
      region: 'us-east-1',
      credentials: {
        accessKeyId: keyId,
        secretAccessKey: secretKey
      }
    });

    const command = new getCallerIdentityCommand({});
    await withTimeout(sts.send(command), 5000);

    console.log('✅ AWS credentials: Valid');
    return { status: 'valid', message: 'AWS credentials validated' };
  } catch (error) {
    console.log(`❌ AWS credentials test failed: ${error.message}`);
    return { status: 'error', message: error.message };
  }
}

/**
 * Test Anthropic API key
 */
async function testAnthropic() {
  console.log('\n=== Testing Anthropic API Key ===');

  const apiKey = process.env.ANTHROPIC_API_KEY;

  if (!apiKey) {
    console.log('❌ ANTHROPIC_API_KEY not set');
    return { status: 'error', message: 'Not set' };
  }

  if (isCanaryValue(apiKey)) {
    console.log('⚠️  Anthropic API key appears to be a canary/test value');
    return { status: 'canary', message: 'Test value' };
  }

  try {
    const response = await fetch('https://api.anthropic.com/v1/requests', {
      method: 'GET',
      headers: {
        'x-api-key': apiKey,
        'anthropic-version': '2023-06-01',
        'content-type': 'application/json',
      },
      signal: AbortSignal.timeout(5000)
    });

    if (response.status === 401 || response.status === 403) {
      console.log('❌ Anthropic API key: Invalid');
      return { status: 'error', message: 'Invalid API key' };
    }

    if (response.ok || response.status === 400) {
      console.log('✅ Anthropic API key: Valid');
      return { status: 'valid', message: 'API key validated' };
    }

    console.log(`⚠️  Unexpected status: ${response.status}`);
    return { status: 'unknown', message: `Status ${response.status}` };
  } catch (error) {
    console.log(`❌ Anthropic API key test failed: ${error.message}`);
    return { status: 'error', message: error.message };
  }
}

